rows=[]
for scene in d['scenes']:
 n=int(scene['id'])
 if not n:continue
 words=' '.join(scene['lines']);model=dict(beatId=scene['sourceBeatId'],englishTerm=terms[n-1],koreanTerm=ko.get(n,scene['title']),meaning=scene['title'],picture=modes[n-1],duration=4,massA=2,massB=1,velocityA=2,velocityB=-1,angularSpeed=1,forceAngle=90,platformSpeed=0);model.update(opts.get(n,{}));steps=[dict(anchor=words.split('.')[0],formula=formula.get(n,''),meaning='',model=model)]
 for anchor,change,eq in extra.get(n,[]):
  assert words.find(anchor)>0,(n,anchor)
  nextModel=dict(model);nextModel.update(change);steps.append(dict(anchor=anchor,formula=eq,meaning='',model=nextModel))
 positions=[words.find(x['anchor']) for x in steps];assert positions==sorted(positions)
 rows.append(dict(sceneId=scene['id'],sourceBeatId=scene['sourceBeatId'],shot=dict(beatId=scene['sourceBeatId'],durationSeconds=0,stepSeconds=[],stepPositions=[],steps=steps),actualSpeechTiming=False))
